//   connMaxGap: largest gap between consecutive sorted ranks
//   suitPattern:"r"|"tt"|"sss"
//   isPaired:   boolean
//   pairRank:   if paired, the pair rank (0=2 .. 12=A)
//   isTrips:    boolean (optional, only for trips)
// ============================================================================

